export const shadeBoost = (o: number, fill?: string): number =>
  (fill && o < 1 ? Math.min(0.7, o * 1.25) : o);

export function resolveShapeFaces(
  kind: string, rotDeg?: number, flat?: boolean, viewYaw?: number, pitchView?: boolean,
): { faces: ShapeFace[] | undefined; rot: number } {
  let faces: ShapeFace[] | undefined;
  let rot = SHAPE_ROT[kind] ?? 0;
  const builder = SHAPE_BUILDERS[kind];
  // 좌우 시점(지적) — 6도 스텝으로 갈무리해 굽는 판 수를 묶는다.
  const vq = viewYaw ? Math.max(-36, Math.min(36, Math.round(viewYaw / 6) * 6)) : 0;
  if ((rotDeg !== undefined || vq !== 0 || pitchView) && builder) {
    /* 기본은 정면(지적: 사선이 어색) — rotDeg 0이 요잉 0(정면 아래)이 되도록 굽는다.
       건물은 rotDeg가 없어 좌우 시점(vq)만 받는다. */
    // 16방향(요청: 원작 스프라이트처럼 22.5도 스텝) — 자연스러운 회전 단위.
    const bucket = rotDeg !== undefined ? ((Math.round(rotDeg / 22.5) * 22.5) % 360 + 360) % 360 : 0;
    /* ★ 열쇠에 **회전 칸(spinTag)**도 실린다(지적: "회전 설정한 포지 톱니바퀴 코어
       디스크 서플 팬 아무것도 안돌아") — 원인이 정확히 이 한 줄이었다. 굽는 판의
       열쇠(buildingSpriteBake)에는 spinTag가 있었는데, **면 목록을 만드는 이 캐시**
       에는 없었다. 그래서 처음 구운 칸의 면 배열이 영원히 재사용됐고, 회전 칸이
       0→1→2로 돌아도 빌더가 다시 안 불려 그림이 한 칸에 얼어붙어 있었다.
       (자세·불빛이 여기 실려 있는 것과 같은 까닭이다 — 굽는 동안만 서는 깃발을
        읽는 빌더는 그 깃발을 열쇠에 함께 실어야 한다.) */
    const key = `${kind}:${bucket}:${flat ? 1 : 0}:${vq}:${pitchTag(pitchView)}:${headTag(kind)}`
      + `:${poseTag(kind)}:${litTag(kind)}:${spinTag(kind)}`;
    let f = HEAD_FACES.get(key);
    if (!f) {
      /* vq는 요잉이 아니라 시각 밀림(지적: 돌리면 모양이 찌그러짐) — 모델은 제 방향
         (bucket)만 요잉하고, 시각은 깊이 비례 가로 밀림(소실점 이동)으로만 반영한다. */
      const sh = Math.tan((vq * Math.PI) / 180);
      // bake(부품 번호 새로 세기)를 가장 바깥에 둔다 — 굽는 판 하나가 곧 부품 한 벌이다.
      const bake0 = (): ShapeFace[] => withViewShear(sh, () => withYaw(-bucket, builder));
      const baked = pitchView ? (): ShapeFace[] => withPitchView(bake0) : bake0;
      f = bake(() => (flat ? withTopView(baked) : baked()));
      HEAD_FACES.set(key, f);
    }
    faces = f;
  } else if (!builder) {
    rot += rotDeg ?? 0;
  }
  faces = faces ?? (flat ? SHAPE_FACES_TOP[kind] : undefined) ?? SHAPE_FACES[kind];
  return { faces, rot };
}
/* 구운 판의 실제 바닥(재재지적: 드론·해처리가 떠 있고 그림자가 이상하다) — 상자
   바닥 기준 어림은 모델이 상자를 다 안 채우면(해처리 둔덕 등) 그림자가 발보다 한참
   아래에 깔렸다. 알파를 성글게 훑어 가장 낮은 그린 픽셀 줄을 재고, 그림자를 거기에
   붙인다. 판은 캐시되므로 측정도 한 번뿐이다. */
/* 내용물 상자(재지적: 유닛·그림자·선택 고리가 다 안 맞음) — 바닥(y)만이 아니라 실제
   그려진 픽셀의 가로 중심(cx)까지 잰다. 내용물이 16-상자 안에서 치우친 모델은 상자
   중심에 붙인 그림자·링이 몸과 어긋났다. 전 픽셀 스캔, 캐시당 한 번. */
/** 잉크 훑기(getImageData)에 든 시간 — 굽기 한 장의 값이 어디서 오는지 가르는 자다(아래 ★).
 *  판을 GPU가 들고 있으면 이 한 줄이 파이프라인을 세워(readback) 수십 ms가 되기도 한다. */
/* ★ **굽기 환경**(굽기 일꾼 준비) ──────────────────────────────────────────────────────────
   굽는 함수(rasterUnit9·rasterBld9와 그 아래 helpers)는 DOM을 직접 안 만진다 — 캔버스를 만드는 손과 한도만 이 표로
   받는다. 메인은 DOM 캔버스(창고·계수기 newCanvas9)를, 굽기 일꾼은 OffscreenCanvas를 꽂는다. 폰은 지금 그대로다
   (일꾼을 안 띄우면 메인의 손이 그대로 굽는다). 기기 한도(DEV9)는 메인이 초기화 뒤 여기 베낀다. */
export type BakeCv9 = HTMLCanvasElement | OffscreenCanvas;
export type BakeCtx9 = CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D;
/** 2D 문맥 — 둘의 getContext 서명이 달라 합 타입에서 곧장 못 부른다. */
export const ctx2d9 = (cv: BakeCv9, opts?: CanvasRenderingContext2DSettings): BakeCtx9 | null =>
  (cv as HTMLCanvasElement).getContext("2d", opts) as BakeCtx9 | null;
export const BAKE_ENV9: {
  /** 새 캔버스(크기 0) — tag는 계수용 이름표. */
  mk: (tag: string) => BakeCv9;
  /** 잘라 담을 판(w×h) — 메인은 창고(takeStored9)에서 먼저 꺼낸다. */
  out: (w: number, h: number, tag: string) => BakeCv9;
  /** 빌림터 한 장 상한·빌림터 총량(바이트) · 판 한 변 상한 */
  oneMax: number; poolBytes: number; sideMax: number;
} = {
  mk: () => (typeof document !== "undefined" ? document.createElement("canvas") : new OffscreenCanvas(0, 0)),
  out: (w, h, tag) => { const c9 = BAKE_ENV9.mk(tag); c9.width = w; c9.height = h; return c9; },
  oneMax: 8 * 1024 * 1024, poolBytes: 24 * 1024 * 1024, sideMax: 2304,
};
export const SCAN_MS9 = { frame: 0, win: 0, last: 0 };
export function contentBox(cv: BakeCv9): { bot: number; cx: number; top: number; w: number } {
  const tS9 = pNow();
  const c2 = ctx2d9(cv, { willReadFrequently: true });
  if (!c2 || cv.width === 0 || cv.height === 0) return { bot: cv.height, cx: cv.width / 2, top: 0, w: cv.width };
  const { data, width, height } = c2.getImageData(0, 0, cv.width, cv.height);
  const scan9 = pNow() - tS9;
  SCAN_MS9.frame += scan9;
  SCAN_MS9.win += scan9;
  let bot = 0;
  let top = height;
  let minX = width;
  let maxX = 0;
  for (let y = height - 1; y >= 0; y -= 1) {
    const row = y * width * 4;
    for (let x = 0; x < width; x += 1) {
      if (data[row + x * 4 + 3] > 10) {
        if (bot === 0) bot = y + 1;
        if (y < top) top = y;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
      }
    }
  }
  if (bot === 0) return { bot: cv.height, cx: cv.width / 2, top: 0, w: cv.width };
  /* 잉크 폭(전수조사: "너무 크게/작게 그려지는 것") — 상자는 등급대로 같아도 모델이
     상자를 채우는 몫이 제각각이라, 같은 소형끼리도 어떤 놈은 커 보이고 어떤 놈은
     작아 보인다. 그 몫을 재서 그리기 단계가 되돌린다. */
  return { bot, cx: (minX + maxX + 1) / 2, top, w: maxX - minX + 1 };
}
/* ★ 잉크 상자를 **모형 좌표로 기억한다**(지적: "모바일에서 저그 본진에서 여전히 버벅임.
   특히 일꾼 자원 캐는 곳이 심하고 크게 확대하면 더 심함") ─────────────────────────────
   실측 — 굽는 판의 잉크 상자를 잡는 훑기(getImageData + 전수 주사)에 드는 값이다
   (폰 판, CPU를 6배 느리게 걸어 저사양 기기에 맞췄다):
     한 변 458px 11.2ms · 660px 24.4ms · 914px 44.6ms · 1300px 85.6ms
   폰의 한 프레임이 50ms(20Hz)이므로 **고배율에서는 건물 한 채를 구울 때 이 훑기만으로
   한 프레임을 통째로 먹는다.** 배율을 바꾸면 판 열쇠의 크기 칸이 한꺼번에 갈려 화면 안
   건물이 전부 다시 구워지는데, 저그 본진처럼 무거운 모델이 몰린 자리(해처리 1727면 ·
   익스트랙터 2722면 · 크립 · 미네랄 · 드론들)에서는 그 훑기가 줄줄이 쌓여 수백 ms가
   멈춘다. 판은 배율의 제곱으로 커지므로 확대할수록 심해진다 — 지적 그대로다.
   그런데 훑어서 얻는 값은 **판 크기와 무관하다**. 굽기의 변환이
     화소 = 원점 + 배수 × 모형좌표
   꼴이라(unitSprite·buildingSprite의 setTransform·translate·scale), 모형 안에서 잉크가
   차지하는 자리는 pxq·sideQ·B가 무엇이든 같다. 실측으로도 판 한 변을 3배 바꿔 재면
   모형 좌표 상자가 **0.053 모형단위** 안에서 같다(= 안티에일리어싱 1화소).
   그러니 한 번만 훑어 모형 좌표로 적어 두고, 다음부터는 그 상자를 이 판의 배수로
   되돌린다. 기억 열쇠에서 크기(pxq·sideQ)와 기기 배수(B)와 **임자 색**을 뺀다 — 색은
   칠하는 값만 바꿀 뿐 덮는 자리를 안 바꾼다. 그래서 한 종류·한 각을 한 번 재면 배율을
   아무리 오가도, 임자가 몇이든 다시 안 훑는다.
   ⚠ 안티에일리어싱 가장자리가 모형 좌표에서 판 크기에 따라 조금 다르므로(1화소 ÷ 배수),
     자를 때 여유를 1 → 2화소로 넓혔다(위 실측의 0.053이 가장 큰 판에서도 3화소 안이다).
   ⚠ 첫 굽기도 **되돌린 상자를 쓴다** — 훑은 값과 되돌린 값이 한 화소쯤 다를 수 있는데,
     그 상자는 자르기뿐 아니라 자리 맞춤(bot·cx·w)에도 쓰이므로 배율마다 값이 달라지면
     건물이 배율을 오갈 때 미세하게 흔들린다. 한 우물에서 나오게 한다. */
export const INK_MODEL_CACHE = new Map<string, [number, number, number, number]>();
/** 기억 상한 — 종류 × 각 × 자세 × 등급이라 실제로는 수천을 안 넘지만, 못을 박아 둔다. */
export const INK_MODEL_MAX = 8192;
/** 이 판의 잉크 상자 — 기억해 둔 모형 상자가 있으면 훑지 않는다.
 *  @param ox,oy 모형 원점이 앉는 화소 자리 @param s 모형 한 단위의 화소 크기 */
export function inkBoxOf(
  cv: BakeCv9, memo: string, ox: number, oy: number, s: number,
): { bot: number; cx: number; top: number; w: number } {
  let m = s > 0 ? INK_MODEL_CACHE.get(memo) : undefined;
  if (m === undefined) {
    const box = contentBox(cv);
    if (s <= 0) return box;
    m = [(box.cx - box.w / 2 - ox) / s, (box.top - oy) / s,
      (box.cx + box.w / 2 - ox) / s, (box.bot - oy) / s];
    if (INK_MODEL_CACHE.size >= INK_MODEL_MAX) INK_MODEL_CACHE.clear();
    INK_MODEL_CACHE.set(memo, m);
  }
  const x0 = ox + m[0] * s;
  const x1 = ox + m[2] * s;
  const top = Math.max(0, Math.min(cv.height - 1, Math.floor(oy + m[1] * s)));
  const bot = Math.max(top + 1, Math.min(cv.height, Math.ceil(oy + m[3] * s)));
  return { bot, top, cx: (x0 + x1) / 2, w: Math.max(1, x1 - x0) };
}
/* ── 구운 판을 잉크에 맞춰 잘라 낸다(재생 부하 개선) ──────────────────────────
   왜 이것이 가장 큰 자리인가 — 굽는 판은 **16 모델 단위 정사각**이다(unitSprite가
   `c2.scale(pxq/16, pxq/16)`으로 그 상자를 화면 pxq에 맞춘다). 그런데 정규화가
   맞추는 잉크 상자는 5.2 모델 단위다(NORM_TARGET_INK) — 곧 그림이 실제로 차지하는
   폭은 판의 **3분의 1**뿐이고, 넓이로는 **9분의 1**이다. 나머지 8/9는 투명 픽셀인데
   그것을 그대로 보관하고 그대로 blit해 왔다.
   건물도 같다: pad가 발자국의 62%라 판 한 변이 발자국의 2.24배이고, 잉크는 대략
   1배다 — 넓이의 5분의 1만 쓰인다.

   자르면 두 가지가 한꺼번에 준다:
     · **보관 바이트** — LRU 예산(96MB)을 8인전에서 세 배 넘기던 것이 그 밑으로 내려온다
       (scripts/sprite-check.mjs가 잰 값: 8인 301.9MB → 자른 뒤 그 1/8~1/9).
     · **blit 비용** — 옮기는 픽셀이 그만큼 준다.
   잘라도 그림은 한 톨도 안 바뀐다: 자른 자리(ox·oy)를 함께 들고 다니며 그릴 때
   되돌리므로, 원래 판을 통째로 그린 것과 **픽셀 단위로 같다**. 재는 값들(bot·cx·w)은
   자르기 **전** 좌표계 그대로 둔다 — 발 위치·그림자·체력바가 다 그 자를 쓰기 때문이다. */
export function cropToInk(
  cv: BakeCv9, box: { bot: number; cx: number; top: number; w: number },
  /** ★ 자를 것이 없어도 **반드시 새 판에 옮겨 담는다** — 원판이 빌려 쓰는 것(아래
   *  BAKE_POOL)일 때 쓴다. 안 그러면 다음 굽기가 그 판을 지우는 순간, 보관함에 든
   *  스프라이트가 통째로 빈 그림이 된다. */
  forceCopy = false,
  /** 계량용 이름표 — 어느 자리가 판을 만드는지 가른다(진단의 캔버스만듦). */
  tag9 = "훑기",
): { cv: BakeCv9; ox: number; oy: number } {
  /* 2화소 — 잉크 상자가 훑기가 아니라 **되돌린 값**일 수 있어서다(위 inkBoxOf의 ⚠).
     되돌린 상자는 안티에일리어싱 한 화소만큼 좁을 수 있으므로 한 화소를 더 남긴다. */
  const M = 2;
  const x0 = Math.max(0, Math.floor(box.cx - box.w / 2) - M);
  const x1 = Math.min(cv.width, Math.ceil(box.cx + box.w / 2) + M);
  const y0 = Math.max(0, box.top - M);
  const y1 = Math.min(cv.height, box.bot + M);
  const w = x1 - x0;
  const h = y1 - y0;
  // 잉크가 없거나 이미 꽉 찬 판은 그대로 둔다(자를 것이 없다) — 빌린 판만 예외다.
  const whole9 = w <= 0 || h <= 0 || (w >= cv.width && h >= cv.height);
  if (whole9 && !forceCopy) return { cv, ox: 0, oy: 0 };
  const cw9 = whole9 ? cv.width : w;
  const ch9 = whole9 ? cv.height : h;
  const cx9 = whole9 ? 0 : x0;
  const cy9 = whole9 ? 0 : y0;
  const out = BAKE_ENV9.out(cw9, ch9, tag9);   // 메인은 창고에서 먼저(takeStored9) — BAKE_ENV9 참고
  const c = ctx2d9(out);
  if (!c) return { cv, ox: 0, oy: 0 };
  c.drawImage(cv, cx9, cy9, cw9, ch9, 0, 0, cw9, ch9);
  return { cv: out, ox: cx9, oy: cy9 };
}
export const PATH2D_CACHE = new Map<string, Path2D>();
export const pathOf = (d: string): Path2D => {
  let p = PATH2D_CACHE.get(d);
  if (!p) { p = new Path2D(d); PATH2D_CACHE.set(d, p); }
  return p;
};
/* ── 유닛 스프라이트 캐시(수리·지적: 캔버스 전환 뒤 프레임 뚝뚝) — 병목은 프레임마다
   유닛 하나에 면 8~20장을 '그림자 블러를 켠 채' fill하는 것: 수백 유닛이면 프레임당
   수천 번의 가우시안 블러 합성이라 PC에서도 버벅였다. 같은 (종류·방향·시각·색·크기)
   조합은 한 번만 오프스크린 캔버스에 굽고, 프레임에선 drawImage 한 번으로 찍는다.
   줌 중엔 크기 양자화 칸이 바뀌며 다시 굽지만 멈추면 전부 캐시 적중이다. */
/* ── 부품 등급(LOD, 요청: "모델들의 부품 중요도도 3단계 정도로 나눠서 사양에 따라
      부분 렌더링") ────────────────────────────────────────────────────────────────
   판을 굽는 순간 딱 한 번 거른다. 등급이 캐시 열쇠에 들어가므로 프레임마다 재는 비용이
   없고, 같은 크기·같은 등급이면 판을 그대로 재활용한다.

   등급을 정하는 자는 둘을 곱한 것이다.
     ① 화면에 실제로 몇 픽셀로 그려지는가 — 건물이 14px로 보일 때 리벳을 그리는 것은
        순수한 낭비다. 설정이 필요 없고 효과가 가장 크다(축소해서 볼 때 유닛 수백이
        한꺼번에 작아진다).
     ② 기기 여력 — 느린 기기에서는 한 단 낮춘다. 모바일에서 특히.
   지금은 아무 면에도 등급이 안 달려 있어(전부 기본 1) 이 필터는 아무것도 안 걸러낸다.
   모델을 다시 쓸 때마다 장식에 deco(), 포인트에 accent()를 씌워 나가면 그때부터 는다. */
export const LOD_PX_POINT = 22;
export const LOD_PX_DECO = 44;
/* 유닛 전용 문턱(지적: 상자로 등급을 정하면 상자가 줄어든 종류가 한 단 떨어져 장식이
   사라진다) — 건물은 제 발자국 상자를 거의 꽉 채워 그려지므로 상자 px이 곧 몸 px이지만,
   유닛은 정규화 뒤에도 상자의 32%(NORM_TARGET_INK/16)만 잉크다. 같은 22/44를 쓰면
   유닛만 세 배 후하게 판정된다. 유닛은 잉크 px으로 재고 문턱도 그 자로 옮긴다.
   문턱 값은 **전수로 다시 잡았다**. 앞선 설계의 6.5/13은 12칸짜리 화면 표본
   (타일 8·2.8 × 줌 1·2·4 × 표준·확대)에서만 '하락 0종'이었고, 그 표본이 문턱을
   비껴갔다 — 타일 4·확대·줌1처럼 흔한 화면(128타일 맵을 512px로 보는 자리)에서
   대형 일곱이 3→2로 떨어져 실루엣 광원(lod>=3 게이트)을 잃었다.
   지금 값은 41종 × 타일 1.0~20.9(0.1 눈금) × 줌 1·2·4 × 표준·확대 = 49,200칸을
   **전수로** 돌려 잡았다. 지금 코드 대비 등급이 떨어지는 칸이 0이 되는 상한은
   5.20/11.05(둘 다 골리앗이 정한다)이고, 여기서 조금 물러선 자리가 5.0/11이다.
   이 값에서 하락 0칸 · 상승 13,676칸(더 선명해지는 쪽)이다. 옛 채움 보정의 몫
   (FILL_CACHE)이 방향 버킷에 따라 흔들리므로, 그 몫을 버킷0·최소·최대·평균 넷으로
   바꿔 가며 네 번 다 돌려도 하락은 0칸이었다. */
export const LOD_INK_POINT = 5.0;
export const LOD_INK_DECO = 11;
/** 사양 라디오가 정하는 등급 상한(요청: "LOD 적용 및 성능 3단계로 — 딱 LOD랑 맞고
 *  편하지") — 저 1(형체만) · 중 2(+포인트) · 고 3(+장식). 크기로 정한 등급과 이 상한
 *  중 낮은 쪽이 실제 등급이라, 사양을 내리면 큰 모델도 부품을 덜 그린다. */
export let lodCap = LOD_FINE;

/** 앱이 op.pose로 세우는 문(unitSprite·도록) — poseSet과 같되 되돌림(0)도 이 문으로. */
export function poseSet9(p: number): void { poseNow = p; }

export function lodSetCap(q: number): void {
  lodCap = q <= 1 ? 1 : q === 2 ? LOD_TRIM : LOD_FINE;
}
/** 지금 화면 배율 — 그리기 직전에 UnitLayer가 넣어 준다(lodSetZoom).
 *  크기로 정하는 등급을 **배율이 덮는다**(요청: "2.5배부터 모든 부품 다 표시" ·
 *  앞선 지적: "어느정도 확대하면 크게가 충분한데도 전체 디테일이 안보이는거같아").
 *  까닭: 등급은 '화면에 몇 픽셀로 그려지나'로 정하는데, 그 픽셀에는 배율이 이미
 *  실려 있으므로 크게 확대하면 저절로 올라가야 맞다. 그런데 잉크 몫이 작은 종류
 *  (정규화 뒤 상자의 32%만 잉크인 유닛들)는 4배로 키워도 문턱(11)에 못 닿는 것이
 *  있었다. 배율이 2.5를 넘으면 크기 판정을 건너뛰고 최고 등급에서 시작한다 —
 *  사양 상한(lodCap)과 기기 벌점은 그대로 걸린다. 확대해서 들여다보는 사람은
 *  '지금 이 순간의 한 장'을 보는 것이라 프레임 예산도 그만큼 여유가 있다. */
export let lodZoom = 1;
export const LOD_ALL_ZOOM = 2.5;

export function lodSetZoom(z: number): void {
  lodZoom = z;
}
/** 기기 여력 벌점(0 또는 1) — 프레임이 계속 밀리면 1로 올라 등급이 한 단 내려간다. */
export let lodPenalty = 0;

export let lodSlowFrames = 0;

export let lodFastFrames = 0;
/** 이 크기로 그릴 때의 등급 — 1 형체 / 2 포인트 / 3 장식. */
/** 이 배율 위로는 **기기 벌점을 안 먹인다**(지적: "확대 후 그냥 보고 있는데 디테일이
 *  없어져 — 익스트랙터 창문, 해처리 옥상 가시") ────────────────────────────────────
 *  그 유실의 정체가 이 벌점이다: 34ms 넘는 프레임이 90번 이어지면 등급이 **화면 전체**
 *  에서 한 단 내려가고, 34ms 아래가 240프레임(약 12초) 이어져야 돌아온다. 12배 저그
 *  기지처럼 계속 밀리는 자리에서는 한 번 내려가면 안 돌아온다 — 그래서 '가만히 보고
 *  있는데도' 창과 가시가 없다.
 *  그런데 깊은 배율에서 이 벌점은 **버는 것이 거의 없다**: 화면에 든 것이 몇 개뿐이라
 *  부품을 덜 그려도 굽기 한 번이 조금 싸질 뿐, 프레임을 먹는 것은 그 큰 판들을 찍는
 *  픽셀이다. 반대로 잃는 것은 사람이 확대해서 **보러 온 바로 그것**이다.
 *  그래서 이 선 위로는 벌점을 면제한다. 낮은 배율(화면에 수백이 드는 자리)에서는
 *  종전대로 걸린다 — 거기서는 부품 수가 실제로 프레임을 정한다. */
export const LOD_NO_PENALTY_ZOOM = 5;
export function lodOf(px: number, ptPx = LOD_PX_POINT, dcPx = LOD_PX_DECO): number {
  const base = lodZoom >= LOD_ALL_ZOOM ? LOD_FINE : px < ptPx ? 1 : px < dcPx ? 2 : 3;
  const pen9 = lodZoom >= LOD_NO_PENALTY_ZOOM ? 0 : lodPenalty;
  // 크기가 정한 등급과 사양 상한 중 낮은 쪽 — 거기서 기기 벌점을 또 한 단 뺀다.
  return Math.max(1, Math.min(base, lodCap) - pen9);
}

/* 실루엣 광원(요청: "사양 최고에서는 유닛과 건물 모두 밝음 어두움 표현 필요") —
   판을 다 그린 뒤, **이미 그려진 픽셀 위에만**(source-atop) 세계 광원 방향의 밝기
   기울기를 얹는다.

   왜 이게 필요한가: 이 렌더러의 명암은 두 갈래로 들어온다. 프리미티브(돔·기둥·상자·뿔)는
   제 면의 법선을 광원과 내적해 스스로 밝기를 매기지만(faceLight), 손으로 그린 몸판
   (bodyFace)은 그냥 단색이다 — bodyFace(d)는 말 그대로 [d, 1]이다. 그래서 프리미티브로
   지은 모델(시즈탱크·골리앗)은 입체로 보이고, 손으로 그린 모델은 납작하다.
   지적한 오버로드가 정확히 뒤쪽이다: 몸통이 bodyFace(타원) 한 장이라 어느 각도에서도
   같은 색이었다("오버로드 몸도 입체인데 빛 효과가 안 들어감").

   면마다 고치려면 모델 아흔 개를 다 손봐야 하고, 손 그림 면에는 법선이라는 것이 아예
   없다. 대신 실루엣 전체에 한 장을 얹으면 손 그림이든 프리미티브든 똑같이 형태가 산다.
   판은 어차피 한 번만 굽고 캐시되므로 프레임당 비용은 0이고, 이미 명암이 있는 모델에도
   해가 없도록 기울기는 얕게 잡았다(밝은 쪽 +14%, 어두운 쪽 -20%).

   광원은 세계 왼쪽 앞(faceLight와 같은 방향)이라 화면에서는 좌상 → 우하다.
   최고 등급(장식까지 그리는 판)에서만 얹는다 — 작게 그릴 땐 어차피 안 보인다. */
export function silhouetteLight(c2: BakeCtx9, cv: BakeCv9): void {
  const prev = c2.getTransform();
  c2.setTransform(1, 0, 0, 1, 0, 0);
  c2.globalCompositeOperation = "source-atop";
  c2.globalAlpha = 1;
  const g = c2.createLinearGradient(0, 0, cv.width, cv.height);
  g.addColorStop(0, "rgba(255,255,255,0.14)");
  g.addColorStop(0.42, "rgba(255,255,255,0)");
  g.addColorStop(0.58, "rgba(0,0,0,0)");
  g.addColorStop(1, "rgba(0,0,0,0.20)");
  c2.fillStyle = g;
  c2.fillRect(0, 0, cv.width, cv.height);
  c2.globalCompositeOperation = "source-over";
  c2.setTransform(prev);
}
/** 판 한 장의 한 변 상한(장치 픽셀) — 이보다 커야 하는 요청은 굽지 않고 **직접 그리기**로
 *  떨어진다(호출부가 판이 없을 때의 길을 이미 갖고 있다). 예산(LRU)은 '여러 장이 쌓여'
 *  터지는 것을 막지만, 한 장이 통째로 거대한 경우는 못 막는다 — 이 문이 그것을 막고,
 *  그래서 크기 대비 상수의 상한이 필요 없어졌다.
 *  값 1536은 실측으로 잡았다(DPR 2): 흔히 가장 큰 그림인 '깊게 확대한 배틀크루저'가
 *  요청 271px → 장치 940px이라 1024로 두면 문턱에 바로 닿아, 제일 눈에 띄는 유닛이
 *  늘 캐시를 못 타고 매 프레임 다시 그려진다. 1536이면 그 판(9MB)까지 캐시에 들어오고,
 *  예산 96MB 안이라 그런 판이 열 장 쌓여도 LRU가 감당한다. */
/* 1536 → 2304(요청: "상한 올려") — 배율 맨 위 칸이 16배가 되면서, 큰 유닛은 이 문에
   걸려 판을 늘려 찍느라 뿌옇게만 커졌다. 한 변을 1.5배로 열면 화소는 2.25배다.
   ★ 무한정 못 올리는 까닭은 **판 한 장의 무게**다: 한 변 2304의 판은 RGBA로 21MB이고,
     3072면 38MB라 예산(아래 SPRITE_BYTES_MAX) 한 장이 통째로 3분의 1을 먹는다. 2304면
     한 장 21MB에 예산 128MB라 큰 판 여섯 장까지 함께 산다 — 16배에서 화면에 드는 큰
     유닛 수가 그 언저리다.
   ★ 그래도 넘는 것(배틀크루저·캐리어를 16배로 보는 자리)은 종전대로 늘려 찍는다.
     그림이 사라지지는 않고 또렷함만 그 선에서 멈춘다. */
export const SPRITE_SIDE_MAX = BAKE_ENV9.sideMax;
export const DECAL_KINDS = new Set(["creeppatch", "creeppatch2", "creeppatch3"]);
/** 캔버스 한 장이 먹는 바이트 — 픽셀당 RGBA 4바이트. */
export const canvasBytes = (cv: { width: number; height: number }): number => cv.width * cv.height * 4;
/** ★ 캔버스가 물고 있던 **뒷그림을 그 자리에서 돌려준다** ────────────────────────────
 *  보관함에서 빼는 것(Map.delete)은 '이 자바스크립트 객체를 더 안 쓴다'는 말일 뿐이고,
 *  그 뒤에 달린 뒷그림(폭×높이×4바이트)은 쓰레기 수거가 돌아야 풀린다. 판을 한두 장
 *  버릴 때는 아무래도 좋은 차이지만, 줌·3D 전환처럼 **한 프레임에 수백 장**을 갈아치우는
 *  자리에서는 그 시차가 곧 봉우리다: 새 세대를 다 굽는 동안 옛 세대의 뒷그림이 아직
 *  살아 있어, 예산이 말하는 두 배 가까이가 실제로 잡혀 있다. 폰은 거기서 죽는다.
 *  크기를 0으로 만들면 브라우저가 그 자리에서 뒷그림을 놓는다 — 캔버스에게 "끝났다"를
 *  말하는 유일한 길이고, 어느 브라우저에서나 같다. */
export const releaseCanvas = (cv: BakeCv9): void => {
  cv.width = 0;
  cv.height = 0;
};
/* ★ **굽는 판을 빌려 쓴다**(질문: "사파리에서 메모리를 몰라 예산을 적게 유지하면
   오히려 터질 확률이 안 올라가나?") ─────────────────────────────────────────────────
   그 물음이 옳다. 예산(LRU)이 막는 것은 **머물러 있는 판들의 합**인데, 폰에서 실제로
   터지던 자리는 거기가 아니었다 — 줌·기울임이 한 칸 바뀌면 열쇠가 통째로 안 맞아
   **한 프레임에 한 세대를 다시 굽고**(그 자리 SPRITE_BYTES_MAX 주석), 그동안 굽는 판
   수백 장을 잡았다 놓는다. 그 봉우리는 예산과 무관하다. 그러니 예산을 더 죄면 머무는
   몫만 줄고 **다시 굽는 횟수는 오히려 는다** — 곧 그 봉우리를 더 자주 밟는다. 어느
   선 밑으로는 죄는 것이 안전이 아니라 위험이다.
   답은 예산을 키우는 것(모르는 기기에 대고 낙관하는 일)이 아니라 **다시 굽기를 싸게
   만드는 것**이다. 굽는 판은 그리고 나면 잘라 담고 버리는 소모품이라, 같은 크기를 다시
   달라고 할 때가 잦다(같은 발자국의 건물들·같은 세대의 다시 굽기). 크기별로 몇 장만
   빌려 두고 지워 쓰면 큰 뒷그림을 잡았다 놓는 일이 통째로 사라진다.
   ★ 크기가 **정확히 같을 때만** 빌린다 — 큰 판을 작은 요청에 빌려주면 잉크 훑기가 그
     넓이를 다 훑어 되레 느려진다(첫 판에서 이 함정을 봤다).
   ★ 빌린 판은 스프라이트로 나갈 수 없다 — 다음 굽기가 지운다. 그래서 자를 것이 없어도
     반드시 새 판에 옮겨 담는다(cropToInk의 forceCopy). */
export const BAKE_POOL: BakeCv9[] = [];
/* ★ 빌림터는 **바이트로** 죈다(같은 지적) — 장수로만 죄면 12배에서 8MB짜리 굽는 판
   셋이 경기 내내 잡혀 있다. 폰의 판 예산(32/16MB)에 견주면 그것만으로 예산 하나를
   더 쓰는 셈이다. 한 장이 너무 크면 아예 안 빌려 두고(그런 크기는 어차피 드물어
   되쓸 일도 적다) 그 자리에서 놓는다. */
/* 유닛까지 이 빌림터를 쓰게 되어(unitSpriteBake의 ★) 한 칸을 넓힌다 — 종류마다 한 변이
   다르고 빌림터는 **같은 한 변**만 되쓰므로, 두 칸이면 종류가 번갈아 나올 때 늘 빗나간다.
   한 장 상한도 12배·dpr 3의 유닛 판(702² = 2.0MB)이 확실히 들어가게 3MB로 올린다.
   ★ 빌림터는 예산 압박이 오면 통째로 놓는다(trimSpriteCache의 ★) — 그래서 이 몫이
     판 예산과 겹쳐 메모리를 밀어 올리지는 않는다. */
/* ★ 3 → 16(실측: `캔버스만듦[초당360 · 훑기153 빌림122 물들이기68]`) — 빌림터가 **같은 한 변**만 되쓰는데
   유닛은 종류·배율마다 한 변이 달라, 세 칸으로는 거의 늘 빗나가 초당 백스물두 장을 새로 만들고 있었다.
   캔버스 하나는 제 배킹(iOS면 IOSurface)을 갖고, 그 회전이 곧 웹킷의 회수(=그리기 멎음)를 부른다.
   칸을 늘려도 **바이트로 죄므로**(BAKE_POOL_BYTES) 메모리 봉우리는 그대로고, 압박이 오면 통째로 놓는다. */
export const BAKE_POOL_MAX = 16;
/* 한 장 상한·총량은 BAKE_ENV9(oneMax·poolBytes)에 있다 — 메인이 DEV9에서 베끼고, 일꾼은 제 것을 받는다. */
/** 그 크기의 굽는 판을 빌린다 — 빌림터에 있으면 지워서 주고, 없으면 새로 짓는다. */
export const bakeCanvas = (side: number): BakeCv9 | null => {
  const i9 = BAKE_POOL.findIndex((c) => c.width === side && c.height === side);
  if (i9 >= 0) {
    const [cv9] = BAKE_POOL.splice(i9, 1);
    const c9 = ctx2d9(cv9);
    if (!c9) return null;
    c9.setTransform(1, 0, 0, 1, 0, 0);
    c9.clearRect(0, 0, side, side);
    return cv9;
  }
  /* ★ 굽는 판만은 **창고에서 안 꺼낸다** — 이 판은 곧바로 잉크를 훑는(getImageData) 자리라 첫 문맥을
     `willReadFrequently`로 열어야 한다(아래 ★). 창고의 판은 그 규약 없이 열린 것일 수 있어, 꺼내 쓰면
     훑기가 GPU 되읽기로 떨어진다(그 값이 한때 2초에 599ms였다). 여기는 빌림터(BAKE_POOL)로 되쓴다. */
  const cv9 = BAKE_ENV9.mk("빌림");
  cv9.width = side;
  cv9.height = side;
  /* ★ 빌림터의 판은 **읽을 판**이다(계측: 2초에 굽기 767ms 가운데 **훑기 599ms** — 78%) ─────────────
     굽는 자리는 이 판에 모형을 그리고 곧바로 잉크를 훑는다(contentBox의 getImageData). 그런데 브라우저는
     기본으로 캔버스를 GPU에 얹으므로, 그 한 줄이 GPU→CPU **되읽기**가 되어 파이프라인을 세운다 — 한 장에
     수십 ms가 나던 값(최악판 probe 120ms)의 대부분이 여기였다.
     첫 문맥을 `willReadFrequently`로 열면 브라우저가 이 판을 CPU 메모리에 두고, 되읽기가 메모리 복사가 된다.
     이 판은 **화면에 안 나간다** — 다 구우면 잉크만큼 잘라 새 판(cropToInk)에 옮겨 담고 여기로 돌아온다.
     그래서 CPU에 두어도 찍기(blit)는 한 톨도 안 느려진다: 화면에 찍히는 것은 잘라 낸 그 새 판이다.
     빌림터에서 되쓰는 길(위)은 이미 있는 문맥을 그대로 얻으므로 이 규약이 그대로 이어진다. */
  ctx2d9(cv9, { willReadFrequently: true });
  return cv9;
};
/** 다 쓴 굽는 판을 돌려준다 — 빌림터가 차면 가장 오래된 것을 그 자리에서 놓는다. */
export const freeBakeCanvas = (cv: BakeCv9): void => {
  if (canvasBytes(cv) > BAKE_ENV9.oneMax) { releaseCanvas(cv); return; }
  BAKE_POOL.push(cv);
  let sum9 = BAKE_POOL.reduce((a9, c9) => a9 + canvasBytes(c9), 0);
  while (BAKE_POOL.length > BAKE_POOL_MAX || (sum9 > BAKE_ENV9.poolBytes && BAKE_POOL.length > 1)) {
    const old9 = BAKE_POOL.shift();
    if (!old9) break;
    sum9 -= canvasBytes(old9);
    releaseCanvas(old9);
  }
};
/** 두 잉크 상자(픽셀)의 합 — 몸판(임자 면 없음)과 마스크의 합이 옛 '온 판'의 상자다(자·발밑·중심이 그대로). */
export const unionInkBox9 = (
  a: { bot: number; cx: number; top: number; w: number }, b: { bot: number; cx: number; top: number; w: number } | null,
): { bot: number; cx: number; top: number; w: number } => {
  if (!b || !(b.w > 1)) return a;
  const x0 = Math.min(a.cx - a.w / 2, b.cx - b.w / 2);
  const x1 = Math.max(a.cx + a.w / 2, b.cx + b.w / 2);
  return { top: Math.min(a.top, b.top), bot: Math.max(a.bot, b.bot), cx: (x0 + x1) / 2, w: Math.max(1, x1 - x0) };
};
/** 구운 판 한 벌 — 몸판(잉크로 자른 것)과 임자 마스크, 자·자리. 캔버스 종류는 환경이 정한다(BAKE_ENV9). */
/** 래스터가 null을 낸 마지막 까닭(면없음·판큼·캔버스없음·문맥없음) — 굽기 일꾼이 done에 실어 보낸다. */
